package org.apache.commons.cli;

import org.junit.jupiter.api.Test;

import java.lang.reflect.Constructor;
import java.util.ArrayList;
import java.util.LinkedList;
import java.util.List;
import java.util.Properties;
import java.util.function.Consumer;

import static org.junit.jupiter.api.Assertions.*;

class CommandLine_GetOptionPropertiesTest {

    private CommandLine createCommandLine(final List<Option> options) throws Exception {
        Constructor<CommandLine> ctor = CommandLine.class.getDeclaredConstructor(List.class, List.class, Consumer.class);
        ctor.setAccessible(true);
        // args list and deprecatedHandler can be null for handler; args must be non-null
        return ctor.newInstance(new LinkedList<String>(), options, (Consumer<Option>) null);
    }

    @Test
    void testGetOptionProperties_optionNotPresent_returnsEmptyProperties() throws Exception {
        // option to query
        Option query = new Option("q", false, "query option");
        // options list does not contain query
        List<Option> options = new ArrayList<>();
        options.add(new Option("x", false, "other"));

        CommandLine cmd = createCommandLine(options);
        Properties props = cmd.getOptionProperties(query);

        assertNotNull(props);
        assertTrue(props.isEmpty(), "Properties should be empty when option is not present in command line");
    }

    @Test
    void testGetOptionProperties_optionPresentNoValues_returnsEmptyProperties() throws Exception {
        // same Option instance placed into the options list and used for query
        Option present = new Option("p", false, "present option");
        List<Option> options = new ArrayList<>();
        options.add(present);

        CommandLine cmd = createCommandLine(options);
        Properties props = cmd.getOptionProperties(present);

        assertNotNull(props);
        assertTrue(props.isEmpty(), "Properties should be empty when option is present but has no values");
    }

    @Test
    void testGetOptionProperties_optionPresentWithKeyValue_returnsProperty() throws Exception {
        // create option and add a key=value style value which CommandLine is expected to parse into Properties
        Option present = new Option("k", false, "key value option");
        present.getValuesList().add("alpha=beta");
        present.getValuesList().add("one=1"); // additional pair to ensure multiple entries handled

        // include another option to ensure only matching option is processed
        Option other = new Option("o", false, "other");
        other.getValuesList().add("x=y");

        List<Option> options = new ArrayList<>();
        options.add(other);
        options.add(present); // present appears after other

        CommandLine cmd = createCommandLine(options);
        Properties props = cmd.getOptionProperties(present);

        assertNotNull(props);
        // Expect at least the provided key/value pairs to be present
        assertEquals("beta", props.getProperty("alpha"), "Expected property alpha=beta");
        assertEquals("1", props.getProperty("one"), "Expected property one=1");
        // Ensure unrelated option's values were not mixed in
        assertNull(props.getProperty("x"), "Unrelated option values should not appear");
    }
}

